+char *wtap_error_msg_open_failure(const char *filename, int err, const char *err_info)
+{
+	char *msg;
+
+	if (err < 0) {
+		/*
+		 * Wiretap error.
+		 * Get a string that describes what we're opening.
+		 */
+		char *file_description = input_file_description(filename);
+
+		switch (err) {
+
+		case WTAP_ERR_NOT_REGULAR_FILE:
+			msg = ws_strdup_printf("The %s is a \"special file\" or socket or other non-regular file.",
+					   file_description);
+			break;
+
+		case WTAP_ERR_RANDOM_OPEN_PIPE:
+			msg = ws_strdup_printf("The %s is a pipe or FIFO; %s can't read pipe or FIFO files in two-pass mode.",
+					   file_description, get_friendly_program_name());
+			break;
+
+		case WTAP_ERR_FILE_UNKNOWN_FORMAT:
+			msg = ws_strdup_printf("The %s isn't a capture file in a format %s understands.",
+					   file_description, get_friendly_program_name());
+			break;
+
+		case WTAP_ERR_UNSUPPORTED:
+			msg = ws_strdup_printf("The %s contains record data that %s doesn't support.\n"
+					   "(%s)",
+					   file_description, get_friendly_program_name(),
+					   err_info != NULL ? err_info : "no information supplied");
+			break;
+
+		case WTAP_ERR_ENCAP_PER_PACKET_UNSUPPORTED:
+			msg = ws_strdup_printf("The %s is a capture for a network type that %s doesn't support.",
+					   file_description, get_friendly_program_name());
+			break;
+
+		case WTAP_ERR_BAD_FILE:
+			msg = ws_strdup_printf("The %s appears to be damaged or corrupt.\n"
+					   "(%s)",
+					   file_description,
+					   err_info != NULL ? err_info : "no information supplied");
+			break;
+
+		case WTAP_ERR_CANT_OPEN:
+			msg = ws_strdup_printf("The %s could not be opened for some unknown reason.",
+					   file_description);
+			break;
+
+		case WTAP_ERR_SHORT_READ:
+			msg = ws_strdup_printf("The %s appears to have been cut short in the middle of a packet or other data.",
+					   file_description);
+			break;
+
+		case WTAP_ERR_DECOMPRESS:
+			msg = ws_strdup_printf("The %s cannot be decompressed; it may be damaged or corrupt."
+					   "(%s)",
+					   file_description,
+					   err_info != NULL ? err_info : "no information supplied");
+			break;
+
+		case WTAP_ERR_INTERNAL:
+			msg = ws_strdup_printf("An internal error occurred opening the %s.\n"
+					   "(%s)",
+					   file_description,
+					   err_info != NULL ? err_info : "no information supplied");
+			break;
+
+		case WTAP_ERR_DECOMPRESSION_NOT_SUPPORTED:
+			msg = ws_strdup_printf("The %s cannot be decompressed; it is compressed in a way that we don't support."
+					   "(%s)",
+					   file_description,
+					   err_info != NULL ? err_info : "no information supplied");
+			break;
+
+		default:
+			msg = ws_strdup_printf("The %s could not be opened: %s.",
+					   file_description,
+					   wtap_strerror(err));
+			break;
+		}
+		g_free(file_description);
+	} else {
+		msg = ws_strdup_printf(file_open_error_message(err, false), filename);
+	}
+
+	return msg;
+}
