+char *wtap_error_msg_write_failure(const char *in_filename, const char *out_filename,
+							int err, const char *err_info,
+							uint64_t framenum, int file_type_subtype)
+{
+	char *msg;
+	char *in_file_string;
+	char *in_frame_string;
+	char *out_file_string;
+
+	/* Get a string that describes what we're reading from */
+	if (in_filename == NULL) {
+		in_frame_string = g_strdup("");
+	} else {
+		in_file_string = input_file_description(in_filename);
+		in_frame_string = ws_strdup_printf(" %" PRIu64 " of %s", framenum,
+										  in_file_string);
+		g_free(in_file_string);
+	}
+
+	/* Get a string that describes what we're writing to */
+	out_file_string = output_file_description(out_filename);
+
+	switch (err) {
+
+	case WTAP_ERR_UNWRITABLE_ENCAP:
+		/*
+		 * This is a problem with the particular frame we're writing
+		 * and the file type and subtype we're writing; note that,
+		 * and report the frame number and file type/subtype.
+		 */
+		msg = ws_strdup_printf("Frame%s has a network type that can't be saved in a \"%s\" file.",
+					in_frame_string,
+					wtap_file_type_subtype_name(file_type_subtype));
+		break;
+
+	case WTAP_ERR_ENCAP_PER_PACKET_UNSUPPORTED:
+		/*
+		 * This is a problem with the particular frame we're writing and
+		 * the file type and subtype we're writing; note that, and report
+		 * the frame number and file type/subtype.
+		 */
+		msg = ws_strdup_printf("Frame%s has a network type that differs from the network type of earlier packets, which isn't supported in a \"%s\" file.",
+					in_frame_string,
+					wtap_file_type_subtype_description(file_type_subtype));
+		break;
+
+	case WTAP_ERR_PACKET_TOO_LARGE:
+		/*
+		 * This is a problem with the particular frame we're writing
+		 * and the file type and subtype we're writing; note that,
+		 * and report the frame number and file type/subtype.
+		 */
+		msg = ws_strdup_printf("Frame%s is larger than %s supports in a \"%s\" file.",
+					in_frame_string, get_friendly_program_name(),
+					wtap_file_type_subtype_name(file_type_subtype));
+		break;
+
+	case WTAP_ERR_UNWRITABLE_REC_TYPE:
+		/*
+		 * This is a problem with the particular record we're writing
+		 * and the file type and subtype we're writing; note that,
+		 * and report the record number and file type/subtype.
+		 */
+		msg = ws_strdup_printf("Record%s has a record type that can't be saved in a \"%s\" file.",
+					in_frame_string,
+					wtap_file_type_subtype_name(file_type_subtype));
+		break;
+
+	case WTAP_ERR_UNWRITABLE_REC_DATA:
+		/*
+		 * This is a problem with the particular record we're writing
+		 * and the file type and subtype we're writing; note that,
+		 * and report the record number and file type/subtype.
+		 */
+		msg = ws_strdup_printf("Record%s has data that can't be saved in a \"%s\" file.\n"
+					"(%s)",
+					in_frame_string,
+					wtap_file_type_subtype_name(file_type_subtype),
+					err_info != NULL ? err_info : "no information supplied");
+		break;
+
+	case WTAP_ERR_SHORT_WRITE:
+		msg = ws_strdup_printf("A full write couldn't be done to the %s.",
+					out_file_string);
+		break;
+
+	case WTAP_ERR_INTERNAL:
+		msg = ws_strdup_printf("An internal error occurred while writing record%s to the %s.\n(%s)",
+					in_frame_string, out_file_string,
+					err_info != NULL ? err_info : "no information supplied");
+		break;
+
+	case ENOSPC:
+		msg = ws_strdup_printf("Not all the packets could be written to the %s because there is "
+					"no space left on the file system.",
+					out_file_string);
+		break;
+
+#ifdef EDQUOT
+	case EDQUOT:
+		msg = ws_strdup_printf("Not all the packets could be written to the %s because you are "
+					"too close to, or over your disk quota.",
+					out_file_string);
+  break;
+#endif
+
+	default:
+		msg = ws_strdup_printf("An error occurred while writing to the %s: %s.",
+					out_file_string, wtap_strerror(err));
+		break;
+	}
+	g_free(in_frame_string);
+	g_free(out_file_string);
+
+	return msg;
+}
