+char *wtap_error_msg_close_failure(const char *filename, int err, const char *err_info)
+{
+	char *msg;
+	char *file_string;
+
+	/* Get a string that describes what we're writing to */
+	file_string = output_file_description(filename);
+
+	switch (err) {
+
+	case WTAP_ERR_CANT_CLOSE:
+		msg = ws_strdup_printf("The %s couldn't be closed for some unknown reason.",
+					file_string);
+		break;
+
+	case WTAP_ERR_SHORT_WRITE:
+		msg = ws_strdup_printf("A full write couldn't be done to the %s.",
+					file_string);
+		break;
+
+	case WTAP_ERR_INTERNAL:
+		msg = ws_strdup_printf("An internal error occurred closing the file \"%s\".\n"
+					"(%s)",
+					file_string,
+					err_info != NULL ? err_info : "no information supplied");
+		break;
+
+	case ENOSPC:
+		msg = ws_strdup_printf("Not all the packets could be written to the %s because there is "
+					"no space left on the file system.",
+					file_string);
+	break;
+
+#ifdef EDQUOT
+	case EDQUOT:
+		msg = ws_strdup_printf("Not all the packets could be written to the %s because you are "
+					"too close to, or over your disk quota.",
+					file_string);
+	break;
+#endif
+
+	default:
+		msg = ws_strdup_printf("An error occurred while closing the file %s: %s.",
+					file_string, wtap_strerror(err));
+		break;
+	}
+	g_free(file_string);
+
+	return msg;
+}
